/* eslint-disable */
import React, { useEffect, useState } from "react";
import { ccc } from "@ckb-ccc/connector-react";
import { truncateAddress } from "../utils/stringUtils";

const ConnectWallet: React.FC = () => {
  const { open, disconnect } = ccc.useCcc();
  const signer = ccc.useSigner();

  const [address, setAddress] = useState<string>("");

  useEffect(() => {
    if (!signer) {
      setAddress("");
      return;
    }

    (async () => {
      const addr = await signer.getRecommendedAddress();
      setAddress(addr);
    })();
  }, [signer]);

  return (
    <div className="p-7 border rounded">
      {!signer ? (
        <button className="border rounded px-2 bg-blue-800 hover:bg-blue-900" onClick={open}>
          Connect Wallet
        </button>
      ) : (
        <>
          <p className="border rounded px-2 md:mr-15 mr-7 bg-green-700 hover:bg-green-900">Connected</p>
          <p>Address: {truncateAddress(address)}</p>
          <button onClick={disconnect}>
            Disconnect
          </button>
        </>
      )}      
    </div>
  );
};

export default ConnectWallet;
